(()=>{const go=route=>{if(document.body.classList.contains('menu-open'))document.querySelector('.menu-control')?.click();if(parent!==window)parent.postMessage({type:'fieldbook:navigate',route},location.origin);else location.href='/#'+route;};const section=document.createElement('section');section.style.cssText='padding:60px 7vw;background:#e9e8df;color:#17242b;border-top:1px solid #bec6b6';section.innerHTML='<p style="font:10px monospace;letter-spacing:.15em">THE NEXT CHAPTER</p><h2 style="font:400 42px/1.15 Georgia,serif;margin:20px 0">The stories continue.<br>Now take the controls.</h2><p style="max-width:600px;line-height:1.8;margin:20px 0">Read the mission catalogue, inspect official NASA hardware, or join a guided rover expedition. Your place in this opening story is kept when you return.</p><div style="display:flex;gap:16px;flex-wrap:wrap"><button data-next="missions" style="padding:16px 24px;background:#213c4c;color:white;border:0;border-radius:4px">Continue to the catalogue →</button><button data-next="simulator/opportunity" style="padding:16px 24px;background:#d8b67c;border:0;color:#21313c;border-radius:4px">Begin rover expedition →</button></div>';document.querySelector('footer').before(section);section.querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.next));const menu=document.querySelector('#menu');if(menu){const a=document.createElement('a');a.href='/#missions';a.textContent='Continue the fieldbook →';a.onclick=e=>{e.preventDefault();go('missions');};menu.append(a);}let autoPaused=false,savedScroll=0;addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='fieldbook:visibility')return;const paused=!!window.explorerMotion?.paused;if(!e.data.visible)savedScroll=scrollY;if(!e.data.visible&&!paused){document.querySelector('.motion-control')?.click();autoPaused=true;}if(e.data.visible&&autoPaused){document.querySelector('.motion-control')?.click();autoPaused=false;requestAnimationFrame(()=>requestAnimationFrame(()=>scrollTo({top:savedScroll,behavior:'instant'})));}});})();
